import openpyxl, os
path='/root/data/workbook.xlsx'
print('exists', os.path.exists(path), 'size', os.path.getsize(path) if os.path.exists(path) else None)
wb = openpyxl.load_workbook(path, data_only=False)
for s in wb.sheetnames:
    print(f'=== {s} ===')
    ws = wb[s]
    print('dimensions', ws.max_row, ws.max_column)
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 50), values_only=False):
        for c in row:
            if c.value is not None:
                print(f'  {c.coordinate}: {repr(c.value)}')

